pm.test("Non-empty response", () => {
    const jsonData = pm.response.json();
    // The positive test cases will have created at least 10 events at this point.
    pm.expect(jsonData.length).to.gt(1);
});
const schema = pm.collectionVariables.get("EVENTS_SCHEMA");
const schemaObject = JSON.parse(schema);

pm.test('Schema is valid', () => {
    pm.response.to.have.jsonSchema(schemaObject);
});

pm.test("All requests match query parameters payload schema", () => {
  const jsonData = pm.response.json();
  jsonData.map((item) =>
  pm.expect(item).to.have.jsonSchema(schemaObject.items)
  );
});
